{
  "commonPhenomenon": "通道侧显示支付成功，但平台侧未接收到回调通知，导致资金状态不一致。",
  "facts": [
    {
      "statement": "渠道账单中已存在成功的交易记录。",
      "evidenceIds": [
        "E-006"
      ]
    },
    {
      "statement": "平台侧接收到的回调记录为空。",
      "evidenceIds": [
        "E-006"
      ]
    }
  ],
  "differences": [
    {
      "description": "通道侧的交易终态为成功，而平台侧因缺失回调导致无法确认该笔交易的最终状态，形成状态差异。",
      "evidenceIds": [
        "E-006"
      ]
    }
  ],
  "possibleExplanations": [
    {
      "hypothesis": "通道已成功发送回调通知，但由于网络故障、防火墙拦截或平台网关异常，导致通知未能到达平台。",
      "evidenceIds": [
        "E-006"
      ],
      "verification": "核查平台入口访问日志及消息队列投递记录，确认是否存在来自通道的请求被丢弃或超时；比对通道侧的回调发送时间戳与平台侧的时间窗口。"
    },
    {
      "hypothesis": "通道侧在生成成功结果后，由于内部处理延迟或重试机制问题，导致回调通知晚于平台预期的查询或关单时间点到达，甚至丢失。",
      "evidenceIds": [
        "E-006"
      ],
      "verification": "获取通道侧详细的回调发送日志，确认是否曾尝试发送以及发送次数；检查平台侧是否有针对该订单号的查单请求，并对比查单时间与回调预期时间。"
    },
    {
      "hypothesis": "通道侧虽然显示成功，但实际并未触发向平台的异步通知流程，或者通知内容因验签失败等原因被平台静默丢弃。",
      "evidenceIds": [
        "E-006"
      ],
      "verification": "联系通道方确认该笔交易是否配置了异步通知及通知地址；若平台有接收日志，检查是否有收到报文但因签名验证不通过而被拒绝的记录。"
    }
  ],
  "checkSteps": [
    "使用商户订单号和通道交易号，在通道侧进行可信只读查单，确认当前资金状态确认为成功。",
    "检索平台侧的入口访问日志和消息中间件日志，查找对应时间段内是否有来自该通道的回调请求记录。",
    "比对通道侧的回调发送时间、平台侧的日志时间（注意时区一致性），确认是否存在时间差导致的漏检。",
    "若发现平台有接收记录但状态未更新，检查验签逻辑和业务处理逻辑是否报错。",
    "若无任何接收记录，联系通道技术支持提供该笔交易的回调发送凭证（如IP、时间、报文摘要）。"
  ],
  "missingInformation": [
    "平台侧入口访问日志中关于该时间段内所有HTTP请求的详细记录。",
    "通道侧关于该笔交易回调通知的具体发送时间、目标URL及发送结果状态码。",
    "平台侧消息队列或回调处理服务的健康状态及错误日志。",
    "商户订单号与通道交易号的映射关系确认信息。"
  ],
  "knowledgeCitations": [
    "lost-callback",
    "terminal-conflict"
  ],
  "knowledgeOmissionReason": null
}
